class Reader{constructor(buf){this.buf=buf;this.pos=0;}remaining(){return this.buf.length-this.pos;}byte(){if(this.pos>=this.buf.length)throw new Error('EOF byte');return this.buf[this.pos++];}u16(){return this.byte()|(this.byte()<<8);}u32(){return this.byte()|(this.byte()<<8)|(this.byte()<<16)|(this.byte()<<24);}bits(n,s,e){if(e==null){const bit=2**(s-1);return n%(bit+bit)>=bit?1:0;}return Math.floor((n/2**(s-1))%2**(e-s+1));}double(){const lo=this.u32();const hi=this.u32();const tmp=Buffer.alloc(8);tmp.writeUInt32LE(lo>>>0,0);tmp.writeUInt32LE(hi>>>0,4);return tmp.readDoubleLE(0);}str(){const len=this.u32();if(len===0)return '';if(this.pos+len>this.buf.length)throw new Error('EOF string');const s=this.buf.slice(this.pos,this.pos+len).toString('latin1');this.pos+=len;return s;}}
