function stripWm(src){const s=String(src);const out=[];let i=0;while(i<s.length){const ch=s[i];if(ch==='"'||ch==="'"){const q=ch;out.push(q);i++;while(i<s.length&&s[i]!==q){if(s[i]==='\\'){out.push(s[i++]);if(i<s.length)out.push(s[i++]);}else{out.push(s[i++]);}}if(i<s.length)out.push(s[i++]);continue;}if(ch==='['){let j=i+1,eq=0;while(s[j]==='='){eq++;j++;}if(s[j]==='['){const close=']'+'='.repeat(eq)+']';const at=s.indexOf(close,j+1);if(at<0){out.push(s.slice(i));break;}out.push(s.slice(i,at+close.length));i=at+close.length;continue;}}if(ch==='-'&&s[i+1]==='-'){if(s[i+2]==='['){let j=i+3,eq=0;while(s[j]==='='){eq++;j++;}if(s[j]==='['){const close=']'+'='.repeat(eq)+']';const at=s.indexOf(close,j+1);i=at<0?s.length:at+close.length;continue;}}i+=2;while(i<s.length&&s[i]!=='\n')i++;continue;}out.push(ch);i++;}return out.join('');}
