function anPrUse(proto,ops){let loadkStr=0,loadkNum=0,getG=0,getF=0,getU=0,calls=0,setG=0,setT=0,newT=0,clos=0,loops=0,rets=0;const list=ops||[];for(const op of list){if(!op||!op.name)continue;switch(op.name){case'LOADK':if(typeof op.B==='string'&&op.B.length>0)loadkStr++;else if(typeof op.B==='number')loadkNum++;break;case'GETGLOBAL':getG++;break;case'GETTABLE':case'SELF':getF++;break;case'GETUPVAL':getU++;break;case'CALL':case'TAILCALL':calls++;break;case'SETGLOBAL':setG++;break;case'SETTABLE':setT++;break;case'NEWTABLE':newT++;break;case'CLOSURE':clos++;break;case'FORPREP':case'FORLOOP':case'TFORLOOP':loops++;break;case'RETURN':rets++;break;}}const interesting=loadkStr>0||setG>0||setT>0||(newT>0&&(setT>0||loops>0))||(calls>0&&loadkStr+setG+setT+newT>0)||(clos>0&&calls>0);const xorStub=loadkStr===0&&setG===0&&setT===0&&getU>=1&&(getG+getF)>=2&&(loops>0||calls>0);return{loadkStr,loadkNum,getG,getF,getU,calls,setG,setT,newT,clos,loops,rets,interesting,xorStub,score:loadkStr*12+setG*15+setT*8+newT*3+clos*4+(calls>0&&loadkStr>0?10:0)+(xorStub?-40:0)+(interesting?5:0)};}
